sections.body:
保存为 normal-convention.mjs，执行 node normal-convention.mjs，无额外依赖。光向定义为“表面指向光源”，全部在同一切线基底中。diffuse 只算 max(0,n·l)，不模拟完整 PBR、曝光、阴影或最终屏幕颜色。

```js
/**
 * @file Check tangent-space normal conventions with synthetic samples.
 * @author liliwei
 * @date 2026-11-25
 * @LastEditors liliwei
 * @LastEditTime 2026-11-25
 */
/** @param {number[]} v Finite nonzero vector. @returns {number[]} Unit vector. */
export function unit(v) {
  if (!Array.isArray(v) || v.length !== 3 || !v.every(Number.isFinite)) {
    throw new TypeError('Invalid vector');
  }
  const length = Math.hypot(...v);
  if (!Number.isFinite(length) || length === 0) throw new RangeError('Invalid length');
  return v.map(x => x / length);
}
/** @param {number[]} rgb Linear data in [0,1], not display colors.
 * @param {boolean} flipGreen Whether the source Y convention needs conversion.
 * @returns {number[]} Unit normal in the agreed target tangent basis.
 */
export function decode(rgb, flipGreen = false) {
  if (!Array.isArray(rgb) || rgb.length !== 3 ||
      !rgb.every(x => Number.isFinite(x) && x >= 0 && x <= 1) ||
      typeof flipGreen !== 'boolean') throw new TypeError('Invalid normal sample');
  const [r, g, b] = rgb;
  return unit([2*r-1, (flipGreen ? -1 : 1)*(2*g-1), 2*b-1]);
}
/** @param {number[]} n Normal. @param {number[]} light Surface-to-light direction.
 * @returns {number} Unitless diffuse cosine, without exposure or PBR shading.
 */
export function diffuse(n, light) {
  const a = unit(n), b = unit(light);
  return Math.max(0, Math.min(1, a.reduce((s, x, i) => s + x*b[i], 0)));
}

// Original ideal float samples; no images or AI outputs are loaded.
export const cases = [
  ['target-Y', [0.5, 0.8, 0.9], false],
  ['opposite-Y-unconverted', [0.5, 0.2, 0.9], false],
  ['opposite-Y-converted', [0.5, 0.2, 0.9], true],
];
for (const [name, rgb, flip] of cases) {
  const n = decode(rgb, flip);
  console.log(JSON.stringify({name, normal:n,
    front:diffuse(n,[0,0,1]),
    plusY:diffuse(n,[0,0.6,0.8]),
    minusY:diffuse(n,[0,-0.6,0.8])}));
}
```

输入是理想浮点通道，不是读取 PNG。实际 8 位文件还会发生舍入；本例也不包含纹理过滤、mipmap、压缩、切线变换和强度参数。flipGreen 只能表达已确认的 Y 约定转换，不能自动识别源格式。
